    @Test
    public void testMerge() {
        // Create two TextChunk objects
        TextChunk chunk1 = new TextChunk(10f, 20f, 30f, 40f);
        TextChunk chunk2 = new TextChunk(50f, 60f, 70f, 80f);

        // Merge chunk2 into chunk1
        TextChunk mergedChunk = chunk1.merge(chunk2);

        // Assert that the returned object is the same as chunk1 (this)
        assertSame(chunk1, mergedChunk);

        // Assert that the merged chunk's properties are updated correctly.
        // Since the underlying Rectangle.merge() method is called, we need to verify that the resulting rectangle
        // encompasses both original rectangles.

        // Calculate the expected merged rectangle properties
        float expectedTop = Math.min(10f, 50f);
        float expectedLeft = Math.min(20f, 60f);
        float expectedBottom = Math.max(10f + 40f, 50f + 80f);
        float expectedRight = Math.max(20f + 30f, 60f + 70f);
        float expectedWidth = expectedRight - expectedLeft;
        float expectedHeight = expectedBottom - expectedTop;
        
        assertEquals(expectedTop, mergedChunk.getTop(), 0.001);
        assertEquals(expectedLeft, mergedChunk.getLeft(), 0.001);
        assertEquals(expectedWidth, mergedChunk.getWidth(), 0.001);
        assertEquals(expectedHeight, mergedChunk.getHeight(), 0.001);

        // Another test case, overlapping chunks
        TextChunk chunk3 = new TextChunk(10f, 20f, 30f, 40f);
        TextChunk chunk4 = new TextChunk(20f, 30f, 40f, 50f);

        TextChunk mergedChunk2 = chunk3.merge(chunk4);

        assertSame(chunk3, mergedChunk2);

        float expectedTop2 = Math.min(10f, 20f);
        float expectedLeft2 = Math.min(20f, 30f);
        float expectedBottom2 = Math.max(10f + 40f, 20f + 50f);
        float expectedRight2 = Math.max(20f + 30f, 30f + 40f);
        float expectedWidth2 = expectedRight2 - expectedLeft2;
        float expectedHeight2 = expectedBottom2 - expectedTop2;

        assertEquals(expectedTop2, mergedChunk2.getTop(), 0.001);
        assertEquals(expectedLeft2, mergedChunk2.getLeft(), 0.001);
        assertEquals(expectedWidth2, mergedChunk2.getWidth(), 0.001);
        assertEquals(expectedHeight2, mergedChunk2.getHeight(), 0.001);
    }
